CREATE TABLE `appointments` (
 `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `public_id` CHAR(36) NOT NULL, `tenant_id` BIGINT UNSIGNED NOT NULL, `customer_id` BIGINT UNSIGNED NOT NULL, `professional_id` BIGINT UNSIGNED NOT NULL, `service_id` BIGINT UNSIGNED NOT NULL, `unit_id` BIGINT UNSIGNED NULL, `starts_at` DATETIME(3) NOT NULL, `ends_at` DATETIME(3) NOT NULL, `duration_minutes` SMALLINT UNSIGNED NOT NULL, `post_service_break_minutes` SMALLINT UNSIGNED NOT NULL DEFAULT 0, `price_cents` BIGINT UNSIGNED NOT NULL, `status` ENUM('PENDING','CONFIRMED','IN_PROGRESS','COMPLETED','CANCELED','NO_SHOW') NOT NULL DEFAULT 'PENDING', `notes` VARCHAR(2000) NULL, `source` VARCHAR(64) NOT NULL DEFAULT 'INTERNAL', `canceled_reason` VARCHAR(500) NULL, `reschedule_reason` VARCHAR(500) NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE INDEX `appointments_public_id_key` (`public_id`), INDEX `appointments_tenant_professional_starts_at_ends_at_status_idx` (`tenant_id`,`professional_id`,`starts_at`,`ends_at`,`status`), INDEX `appointments_tenant_customer_starts_at_idx` (`tenant_id`,`customer_id`,`starts_at`), CONSTRAINT `appointments_tenant_fkey` FOREIGN KEY (`tenant_id`) REFERENCES `tenants`(`id`), CONSTRAINT `appointments_customer_fkey` FOREIGN KEY (`customer_id`) REFERENCES `customers`(`id`), CONSTRAINT `appointments_professional_fkey` FOREIGN KEY (`professional_id`) REFERENCES `professionals`(`id`), CONSTRAINT `appointments_service_fkey` FOREIGN KEY (`service_id`) REFERENCES `services`(`id`), CONSTRAINT `appointments_unit_fkey` FOREIGN KEY (`unit_id`) REFERENCES `business_units`(`id`)
) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
